/** Pans only from empty diagram background, so node, edge, and group activation keeps working. */
function isEmptyDiagramBackground(target: EventTarget | null) {
    if (!(target instanceof Element)) return false

    return !target.closest('[data-diagram-id]')
}

interface DiagramCurrentViewportProps {
    data: PositionedDiagramData
    emphasis?: DiagramEmphasisService
    onContextMenu?: (anchorElement: HTMLElement, selection: DiagramSelection) => void
    onSelect: (anchorElement: HTMLElement, selection: DiagramSelection) => void
    service?: Pick<DiagramViewService,
        'getCurrentSelectionSnapshot'
        | 'getViewportScaleSnapshot'
        | 'setViewportScale'
        | 'subscribeCurrentSelection'
        | 'subscribeViewportScale'>
}

const CurrentDiagram = memo(DiagramRenderer)

function ignoreContextMenu() {}

/** Scrollable Current viewport with service-owned visual scale and fixed zoom control. */
export function DiagramCurrentViewport(props: DiagramCurrentViewportProps) {
    const {data, emphasis = diagramEmphasisService, onContextMenu = ignoreContextMenu} = props
    const {onSelect, service = diagramViewService} = props
    const scrollerRef = useRef<HTMLDivElement>(null)
    const scale = useSyncExternalStore(
        service.subscribeViewportScale,
        service.getViewportScaleSnapshot,
        service.getViewportScaleSnapshot,
    )
    const previousOriginRef = useRef<{ x: number, y: number } | null>(null)
    useLayoutEffect(() => {
        const previous = previousOriginRef.current
        const scroller = scrollerRef.current
        if (previous && scroller) {
            scroller.scrollLeft += (data.originX - previous.x) * scale
            scroller.scrollTop += (data.originY - previous.y) * scale
        }
        previousOriginRef.current = { x: data.originX, y: data.originY }
    }, [data.originX, data.originY, scale])
    useDiagramCtrlWheelZoom(scrollerRef, service, service.getViewportScaleSnapshot)
    const canStartPan = useCallback(
        (event: ReactPointerEvent<HTMLElement>) => isEmptyDiagramBackground(event.target),
        [],
    )
    const pan = useDiagramSurfacePan(scrollerRef, { canStartPan })
    const cancelActiveGesture = useCallback(() => { pan.cancelPan() }, [pan])
    const pinch = useDiagramPinchZoom(scrollerRef, service, service.getViewportScaleSnapshot, cancelActiveGesture)
    usePreserveDiagramZoomCenter(scrollerRef, scale, pinch.anchorRef)
    const handleDiagramEscapeRequested = useCallback((event: Event) => {
        if (event.defaultPrevented) return
        if (pan.cancelPan()) {
            event.preventDefault()

            return
        }
        if (emphasis.getTargetSnapshot()?.surface !== 'current') return
        event.preventDefault()
        emphasis.clear()
    }, [emphasis, pan])
    const handleClickCapture = useCallback((event: ReactMouseEvent<HTMLDivElement>) => {
        const pinchSuppressed = pinch.consumeSuppressedClick()
        if (!pinchSuppressed && !pan.consumeSuppressedClick()) return

        event.preventDefault()
        event.stopPropagation()
    }, [pan, pinch])
    const handlePointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => { pan.beginPan(event) }, [pan])
    const handlePointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => { pan.updatePan(event) }, [pan])
    const handlePointerUp = useCallback(() => { pan.completePan() }, [pan])
    const handlePointerCancel = useCallback(() => { pan.cancelPan() }, [pan])

    useEffect(() => {
        diagramKeyboardShortcutService.addEventListener(DIAGRAM_ESCAPE_REQUESTED_EVENT, handleDiagramEscapeRequested)

        return () => diagramKeyboardShortcutService.removeEventListener(DIAGRAM_ESCAPE_REQUESTED_EVENT, handleDiagramEscapeRequested)
    }, [handleDiagramEscapeRequested])

    return (
        <Box sx={{ display: 'flex', flex: 1, minHeight: 0, minWidth: 0, overflow: 'hidden', position: 'relative' }}>
            <Box
                aria-label="Current diagram scroller"
                onClickCapture={handleClickCapture}
                onPointerCancelCapture={pinch.endPointerCapture}
                onPointerCancel={handlePointerCancel}
                onPointerDownCapture={pinch.handlePointerDownCapture}
                onPointerDown={handlePointerDown}
                onPointerMoveCapture={pinch.handlePointerMoveCapture}
                onPointerMove={handlePointerMove}
                onPointerUpCapture={pinch.endPointerCapture}
                onPointerUp={handlePointerUp}
                ref={scrollerRef}
                sx={{ flex: 1, minHeight: 0, minWidth: 0, overflow: 'auto', p: 2, touchAction: 'pan-x pan-y' }}
            >
                <Box data-testid="current-diagram-zoom-surface" sx={{ transformOrigin: 'top left', zoom: scale }}>
                    <CurrentDiagram data={data} emphasis={emphasis} onContextMenu={onContextMenu} onSelect={onSelect} service={service} />
                </Box>
            </Box>
            <DiagramZoomSlider diagramIdentity="Current" reader={service} store={service} />
            <DiagramEmphasisExitButton emphasis={emphasis} surface="current" />
        </Box>
    )
}

import { TextField } from '@mui/material'
import { useState, type ChangeEvent, type KeyboardEvent, type PointerEvent } from 'react'
import {
    DiagramEditSessionService,
} from '../../../services/diagrams/diagram_edit_session_service'
import type {
    MutableDiagramMetaField,
} from '../../../services/diagrams/diagram_edit_types'
import { useEditableDiagramMetadataField } from './use_editable_diagram'
import { diagramFontStyle } from '../formatting/diagram_font_style'
import { useDiagramFormattingScale } from '../formatting/use_diagram_formatting'

/** Edits one New diagram metadata field without opening its details dialog. */
export function DiagramInlineMetadataField({ field, session }: { field: MutableDiagramMetaField, session: DiagramEditSessionService }) {
    const value = useEditableDiagramMetadataField(field, session) ?? ''
    const fontScalePercent = useDiagramFormattingScale('fontScalePercent', session.read)
    const [draftState, setDraftState] = useState({ base: value, value })
    const draft = draftState.base === value ? draftState.value : value
    const [error, setError] = useState<string | null>(null)
    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setDraftState({ base: value, value: event.target.value })
        setError(null)
    }
    const commit = () => {
        const trimmed = draft.trim()
        if (trimmed === value) return
        if (!trimmed) {
            setError(`${field === 'title' ? 'Title' : 'Subtitle'} is required.`)

            return
        }
        if (!session.objects.setMetadataField(field, trimmed)) setError(`${field} could not be saved.`)
    }
    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Escape') {
            setDraftState({ base: value, value })
            setError(null)

            return
        }
        if (event.key !== 'Enter' || (field === 'description' && !event.ctrlKey)) return
        event.preventDefault()
        commit()
    }
    const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => event.stopPropagation()

    return (
        <TextField
            error={!!error}
            helperText={error}
            multiline={field === 'description'}
            onBlur={commit}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
            onPointerDown={handlePointerDown}
            size="small"
            slotProps={{ htmlInput: { 'aria-label': field === 'title' ? 'Diagram title' : 'Diagram subtitle' } }}
            sx={{ '& .MuiInputBase-input': diagramFontStyle(undefined, fontScalePercent, field === 'title' ? 'h6' : 'body2'), minWidth: 240 }}
            value={draft}
            variant="standard"
        />
    )
}

