import { useCallback, useSyncExternalStore } from 'react'
import type {
    DiagramConnectionPoint,
    DiagramEdge,
    DiagramEntityField,
    DiagramGroup,
    DiagramMeta,
    DiagramNode,
    DiagramSequenceFragment,
} from '../../../services/diagrams/diagram_data'
import {
    diagramEditSessionService,
    type DiagramEditSessionService,
